import{_ as a,o as t,c as r,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Home-repair and renovation commencement profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/49-home-repair-profile.md","filePath":"reference/49-home-repair-profile.md","lastUpdated":1788532705000}'),o={name:"reference/49-home-repair-profile.md"};function i(d,e,s,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="home-repair-and-renovation-commencement-profile" tabindex="-1">Home-repair and renovation commencement profile <a class="header-anchor" href="#home-repair-and-renovation-commencement-profile" aria-label="Permalink to &quot;Home-repair and renovation commencement profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The <code>home_repair</code> activity follows B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter XII, “Repairing Houses,” printed pages 53–54 (PDF pages 57–58). It covers beginning repair or renovation work on an existing home.</p><p>The passage separately discusses whitewashing, dismantling a building and moving to another house. Those acts are deliberately excluded, as are new construction, foundation work, roof laying and post-renovation re-entry.</p><p>The available <em>Muhurta Chintamani</em> scan was searched as an independent authority. Its house-building and entry material did not provide a dedicated repair passage that could responsibly be treated as the source of Raman&#39;s formula. This profile therefore cites Raman alone and records the absence of independent textual corroboration instead of manufacturing agreement.</p><h2 id="rule-crosswalk" tabindex="-1">Rule crosswalk <a class="header-anchor" href="#rule-crosswalk" aria-label="Permalink to &quot;Rule crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement</th><th>Product treatment</th></tr></thead><tbody><tr><td>Do not begin repairs Tuesday</td><td>Tuesday is the sole hard weekday exclusion</td></tr><tr><td>Monday, Wednesday and Thursday are best</td><td>These weekdays receive a preference bonus</td></tr><tr><td>Friday with Vrishabha/Tula Lagna and Monday with Karka Lagna are especially suitable</td><td>Visible practitioner check; no unconditional Friday or Lagna claim</td></tr><tr><td>A benefic should occupy Lagna and Chandra should be in an aquatic Rasi</td><td>Visible practitioner check</td></tr><tr><td>Seven Nakshatras are barred only when Mangala transits the same star</td><td>Conditional practitioner check; the stars are not globally rejected</td></tr></tbody></table><p>Sunday and Saturday receive no activity-specific bonus, but the paragraph does not forbid them. Excluding them would turn “best” into “only,” so they remain admissible.</p><h2 id="safety-boundary" tabindex="-1">Safety boundary <a class="header-anchor" href="#safety-boundary" aria-label="Permalink to &quot;Safety boundary&quot;">​</a></h2><p>The source&#39;s chart conditions cannot yet be evaluated identically by every surface. <code>manual_prerequisites</code> therefore prevents an automated result from receiving the <code>Excellent</code> tier. Building permits, structural engineering, utility safety and contractor readiness always take precedence over timing.</p>',10)])])}const m=a(o,[["render",i]]);export{p as __pageData,m as default};
